{
  "meta": {
    "name": "Online Learning Platform",
    "description": "An online learning platform where instructors publish courses and students enroll, complete lessons, and provide reviews, with a freemium model offering access to paid courses and certificates via subscription.",
    "version": "1.0.0"
  },
  "entities": [
    {
      "name": "Course",
      "fields": [
        {
          "name": "title",
          "type": "string",
          "required": true,
          "unique": false
        },
        {
          "name": "description",
          "type": "text",
          "required": false,
          "unique": false
        },
        {
          "name": "price",
          "type": "number",
          "required": false,
          "unique": false,
          "default": 0
        },
        {
          "name": "isFree",
          "type": "boolean",
          "required": false,
          "unique": false,
          "default": true
        }
      ],
      "relations": [
        {
          "name": "lessons",
          "kind": "oneToMany",
          "target": "Lesson",
          "required": false
        },
        {
          "name": "reviews",
          "kind": "oneToMany",
          "target": "Review",
          "required": false
        }
      ],
      "ownable": true
    },
    {
      "name": "Lesson",
      "fields": [
        {
          "name": "title",
          "type": "string",
          "required": true,
          "unique": false
        },
        {
          "name": "videoUrl",
          "type": "url",
          "required": false,
          "unique": false
        },
        {
          "name": "videoFile",
          "type": "string",
          "required": false,
          "unique": false
        }
      ],
      "relations": [
        {
          "name": "course",
          "kind": "manyToOne",
          "target": "Course",
          "required": true
        }
      ],
      "ownable": false
    },
    {
      "name": "Enrollment",
      "fields": [
        {
          "name": "enrollmentDate",
          "type": "datetime",
          "required": false,
          "unique": false,
          "default": "now()"
        }
      ],
      "relations": [
        {
          "name": "course",
          "kind": "manyToOne",
          "target": "Course",
          "required": true
        }
      ],
      "ownable": true
    },
    {
      "name": "LessonCompletion",
      "fields": [
        {
          "name": "completionDate",
          "type": "datetime",
          "required": false,
          "unique": false,
          "default": "now()"
        }
      ],
      "relations": [
        {
          "name": "lesson",
          "kind": "manyToOne",
          "target": "Lesson",
          "required": true
        }
      ],
      "ownable": true
    },
    {
      "name": "Review",
      "fields": [
        {
          "name": "rating",
          "type": "integer",
          "required": true,
          "unique": false
        },
        {
          "name": "comment",
          "type": "text",
          "required": false,
          "unique": false
        }
      ],
      "relations": [
        {
          "name": "course",
          "kind": "manyToOne",
          "target": "Course",
          "required": true
        }
      ],
      "ownable": true
    }
  ],
  "roles": [
    {
      "name": "instructor",
      "description": "Can publish courses and view student progress.",
      "isDefault": false
    },
    {
      "name": "student",
      "description": "Can enroll in courses, mark lessons complete, rate and review.",
      "isDefault": true
    },
    {
      "name": "admin",
      "description": "Platform administrator.",
      "isDefault": false
    }
  ],
  "permissions": [
    {
      "role": "instructor",
      "entity": "Course",
      "actions": [
        "create",
        "read",
        "update",
        "delete"
      ],
      "scope": "own"
    },
    {
      "role": "instructor",
      "entity": "Lesson",
      "actions": [
        "create",
        "read",
        "update",
        "delete"
      ],
      "scope": "all"
    },
    {
      "role": "instructor",
      "entity": "Enrollment",
      "actions": [
        "read"
      ],
      "scope": "all"
    },
    {
      "role": "instructor",
      "entity": "LessonCompletion",
      "actions": [
        "read"
      ],
      "scope": "all"
    },
    {
      "role": "student",
      "entity": "Course",
      "actions": [
        "read"
      ],
      "scope": "all",
      "requiresPlan": "premium"
    },
    {
      "role": "student",
      "entity": "Lesson",
      "actions": [
        "read"
      ],
      "scope": "all",
      "requiresPlan": "premium"
    },
    {
      "role": "student",
      "entity": "Enrollment",
      "actions": [
        "create",
        "read",
        "delete"
      ],
      "scope": "own"
    },
    {
      "role": "student",
      "entity": "LessonCompletion",
      "actions": [
        "create",
        "read",
        "update"
      ],
      "scope": "own"
    },
    {
      "role": "student",
      "entity": "Review",
      "actions": [
        "create",
        "read",
        "update",
        "delete"
      ],
      "scope": "own"
    },
    {
      "role": "admin",
      "entity": "Course",
      "actions": [
        "create",
        "read",
        "update",
        "delete"
      ],
      "scope": "all"
    },
    {
      "role": "admin",
      "entity": "Lesson",
      "actions": [
        "create",
        "read",
        "update",
        "delete"
      ],
      "scope": "all"
    },
    {
      "role": "admin",
      "entity": "Enrollment",
      "actions": [
        "read",
        "delete"
      ],
      "scope": "all"
    },
    {
      "role": "admin",
      "entity": "LessonCompletion",
      "actions": [
        "read",
        "delete"
      ],
      "scope": "all"
    },
    {
      "role": "admin",
      "entity": "Review",
      "actions": [
        "read",
        "delete"
      ],
      "scope": "all"
    }
  ],
  "pages": [
    {
      "name": "Courses",
      "route": "/courses",
      "type": "list",
      "entity": "Course",
      "access": [
        "instructor",
        "student",
        "admin"
      ],
      "fields": [],
      "widgets": []
    },
    {
      "name": "Course Detail",
      "route": "/courses/:id",
      "type": "detail",
      "entity": "Course",
      "access": [
        "instructor",
        "student",
        "admin"
      ],
      "fields": [],
      "widgets": []
    },
    {
      "name": "New Course",
      "route": "/courses/new",
      "type": "form",
      "entity": "Course",
      "access": [
        "instructor",
        "admin"
      ],
      "fields": [],
      "widgets": []
    },
    {
      "name": "Edit Course",
      "route": "/courses/:id/edit",
      "type": "form",
      "entity": "Course",
      "access": [
        "instructor",
        "admin"
      ],
      "fields": [],
      "widgets": []
    },
    {
      "name": "Lessons",
      "route": "/lessons",
      "type": "list",
      "entity": "Lesson",
      "access": [
        "instructor",
        "admin"
      ],
      "fields": [],
      "widgets": []
    },
    {
      "name": "New Lesson",
      "route": "/lessons/new",
      "type": "form",
      "entity": "Lesson",
      "access": [
        "instructor",
        "admin"
      ],
      "fields": [],
      "widgets": []
    },
    {
      "name": "Edit Lesson",
      "route": "/lessons/:id/edit",
      "type": "form",
      "entity": "Lesson",
      "access": [
        "instructor",
        "admin"
      ],
      "fields": [],
      "widgets": []
    },
    {
      "name": "Enrollments",
      "route": "/enrollments",
      "type": "list",
      "entity": "Enrollment",
      "access": [
        "student",
        "admin"
      ],
      "fields": [],
      "widgets": []
    },
    {
      "name": "My Courses",
      "route": "/my-courses",
      "type": "list",
      "entity": "Course",
      "access": [
        "student"
      ],
      "fields": [
        "title",
        "description",
        "price"
      ],
      "widgets": []
    },
    {
      "name": "Instructor Dashboard",
      "route": "/dashboard/instructor",
      "type": "dashboard",
      "access": [
        "instructor"
      ],
      "fields": [],
      "widgets": [
        {
          "type": "stat",
          "label": "Total Students Enrolled",
          "entity": "Enrollment",
          "metric": "count"
        },
        {
          "type": "stat",
          "label": "Total Lessons Completed",
          "entity": "LessonCompletion",
          "metric": "count"
        }
      ]
    },
    {
      "name": "Student Dashboard",
      "route": "/dashboard/student",
      "type": "dashboard",
      "access": [
        "student"
      ],
      "fields": [],
      "widgets": [
        {
          "type": "table",
          "label": "My Enrollments",
          "entity": "Enrollment"
        }
      ]
    },
    {
      "name": "Admin Dashboard",
      "route": "/dashboard/admin",
      "type": "dashboard",
      "access": [
        "admin"
      ],
      "fields": [],
      "widgets": [
        {
          "type": "stat",
          "label": "Total Courses",
          "entity": "Course",
          "metric": "count"
        },
        {
          "type": "stat",
          "label": "Total Students",
          "entity": "Enrollment",
          "metric": "count"
        }
      ]
    },
    {
      "name": "Premium Content",
      "route": "/premium",
      "type": "custom",
      "access": [
        "student"
      ],
      "fields": [],
      "widgets": [],
      "requiresPlan": "premium"
    },
    {
      "name": "Certificates",
      "route": "/certificates",
      "type": "custom",
      "access": [
        "student"
      ],
      "fields": [],
      "widgets": [],
      "requiresPlan": "premium"
    }
  ],
  "businessRules": [
    {
      "type": "plan_gate",
      "id": "premiumContentGate",
      "requiresPlan": "premium",
      "gates": {
        "pages": [
          "Premium Content",
          "Certificates"
        ],
        "entities": [],
        "features": [
          "access_paid_courses",
          "completion_certificates"
        ]
      }
    },
    {
      "type": "ownership",
      "id": "courseOwnership",
      "entity": "Course"
    },
    {
      "type": "ownership",
      "id": "enrollmentOwnership",
      "entity": "Enrollment"
    },
    {
      "type": "ownership",
      "id": "lessonCompletionOwnership",
      "entity": "LessonCompletion"
    },
    {
      "type": "ownership",
      "id": "reviewOwnership",
      "entity": "Review"
    }
  ],
  "plans": [
    {
      "name": "free",
      "price": 0,
      "currency": "usd",
      "interval": "month",
      "isDefault": true,
      "features": [
        "access_free_courses",
        "rate_review_courses"
      ]
    },
    {
      "name": "premium",
      "price": 10,
      "currency": "usd",
      "interval": "month",
      "isDefault": false,
      "features": [
        "access_paid_courses",
        "completion_certificates"
      ]
    }
  ],
  "auth": {
    "strategy": "email_password",
    "providers": [],
    "requireAuth": true
  },
  "assumptions": [
    "There will be an admin role to manage the platform.",
    "Users will have profiles to store their information.",
    "Completion certificates are generated automatically upon course completion for subscribed users."
  ]
}
